import { createClient } from '@supabase/supabase-js';
import { readFileSync } from 'node:fs';
if(process.env.PADELLERIA_LOCAL_VERIFIED!=='1'||process.env.SUPABASE_URL!=='http://127.0.0.1:55021')throw new Error('Local runner required');
const db=createClient(process.env.SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}}),check=({error})=>{if(error)throw error;};
const common={category:'Altro',short_description:'Esempio sintetico LOCAL ONLY, non un’offerta reale.',full_description:'Partner dimostrativo per la verifica locale. Immagini segnaposto.',benefit_title:'10% di sconto',benefit_description:'Vantaggio dimostrativo applicato manualmente in negozio.',conditions:'Offerta fittizia. Mostra la tessera MOVI al personale.',website_url:'https://example.com',contact_url:null,phone:'+39 011 0000000',address:'Via Demo 1',locality:'Località Demo',status:'active',featured:false,valid_from:null,valid_until:null,deleted_at:null};
const rows=[{...common,id:'eded4000-0000-4000-8000-000000000001',name:'MÀSE Demo',slug:'mase-demo',category:'Ristorazione',featured:true,sort_order:1},{...common,id:'eded4000-0000-4000-8000-000000000002',name:'Sport Shop Demo',slug:'sport-shop-demo',category:'Sport',benefit_title:'20% di sconto',valid_from:new Date(Date.now()-86400000).toISOString(),valid_until:new Date(Date.now()+30*86400000).toISOString(),sort_order:2},{...common,id:'eded4000-0000-4000-8000-000000000003',name:'Partner Bozza Demo',slug:'partner-bozza-demo',status:'draft',sort_order:3},{...common,id:'eded4000-0000-4000-8000-000000000004',name:'Partner Inattivo Demo',slug:'partner-inattivo-demo',status:'inactive',sort_order:4}];
for(const row of rows){check(await db.from('movi_partners').upsert(row));}
for(const [i,row] of rows.slice(0,2).entries()){for(const [j,role] of ['logo','cover'].entries()){const path=`${row.id}/eded5000-0000-4000-8000-${String(i*2+j+1).padStart(12,'0')}.jpg`;check(await db.storage.from('movi-partners-media').upload(path,readFileSync(role==='logo'?'public/home/tournaments.jpg':'public/home/hero-bg.jpg'),{contentType:'image/jpeg',upsert:true}));check(await db.from('movi_partners').update({[`${role}_path`]:path}).eq('id',row.id));}}
console.log('LOCAL ONLY: 4 synthetic Partners with 2 logos and 2 covers. Existing Padelleria local admin login reused.');
